rotate.py:
"""Sequence rotation helpers."""


def rotate(items, steps: int) -> list:
    """Return a new list with *items* rotated right by *steps* places.

    Negative steps rotate left. Any whole-number offset wraps around the input;
    an empty input always produces an empty list.
    """
    values = list(items)
    if not values:
        return []
    offset = steps % len(values)
    if offset == 0:
        return values
    return values[-offset:] + values[:-offset]

