import unittest

from rotate import rotate


class RotateTests(unittest.TestCase):
    def test_rotates_right(self):
        self.assertEqual(rotate([1, 2, 3, 4], 1), [4, 1, 2, 3])
        self.assertEqual(rotate([1, 2, 3, 4], 2), [3, 4, 1, 2])

    def test_negative_steps_rotate_left(self):
        self.assertEqual(rotate([1, 2, 3, 4], -1), [2, 3, 4, 1])
        self.assertEqual(rotate([1, 2, 3, 4], -2), [3, 4, 1, 2])

    def test_large_offsets_wrap(self):
        self.assertEqual(rotate([1, 2, 3], 7), [3, 1, 2])
        self.assertEqual(rotate([1, 2, 3], -7), [2, 3, 1])

    def test_zero_multiple_and_empty(self):
        self.assertEqual(rotate([1, 2, 3], 0), [1, 2, 3])
        self.assertEqual(rotate([1, 2, 3], 6), [1, 2, 3])
        self.assertEqual(rotate([], 5), [])

    def test_does_not_mutate_input_and_returns_new_list(self):
        items = ["a", "b", "c"]
        result = rotate(items, 1)
        self.assertEqual(result, ["c", "a", "b"])
        self.assertEqual(items, ["a", "b", "c"])
        self.assertIsNot(result, items)

    def test_single_item(self):
        self.assertEqual(rotate(["only"], -100), ["only"])


if __name__ == "__main__":
    unittest.main()
